#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long sumRemoteness(vector<vector<int>>& grid) {
        int m=grid.size(),n=grid[0].size();
        long long total=0,answer=0;
        for(auto& row:grid)for(int v:row)if(v!=-1)total+=v;
        vector<vector<bool>> seen(m,vector<bool>(n,false));
        int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};
        for(int i=0;i<m;++i)for(int j=0;j<n;++j) {
            if(grid[i][j]==-1||seen[i][j])continue;
            queue<pair<int,int>>q;q.push({i,j});seen[i][j]=true;
            long long sum=0,count=0;
            while(!q.empty()) {
                auto p=q.front();q.pop();sum+=grid[p.first][p.second];++count;
                for(int d=0;d<4;++d) {
                    int x=p.first+dx[d],y=p.second+dy[d];
                    if(x>=0&&y>=0&&x<m&&y<n&&grid[x][y]!=-1&&!seen[x][y]) {
                        seen[x][y]=true;q.push({x,y});
                    }
                }
            }
            answer+=count*(total-sum);
        }
        return answer;
    }
};
